window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-976fec5bf990e4d8"]={"versions": [{"id": "FIG-976fec5bf990e4d8", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Darstellung des AUTOSAR ECUC-Parameter-Definitions-Metamodells (ECU Configuration Parameter Definition) für das BSW-Modul <code>Os</code>.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Konfigurationscontainer, Parameter und Referenzen zur statischen Modellierung von AUTOSAR-OS-Ablaufplänen (<code>OsScheduleTable</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient BSW-Konfigurationstools und dem OS-Code-Generator zur deterministischen Generierung zeitgesteuerter Aktivierungs- und Synchronisationsmechanismen (AUTOSAR OS Skalierbarkeitsklassen SC2 und SC4) auf Basis von Hardware- oder Software-Zählern (<code>OsCounter</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Entitäten & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsScheduleTable</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>0..*</code>):</li>\n<li>Wurzelcontainer einer Schedule Table.</li>\n<li><strong>Parameter:</strong></li>\n<li><code>OsScheduleTableRepeating</code> (<code>EcucBooleanParamDef</code>, <code>1..1</code>): Definiert den Betriebsmodus (zyklische Wiederholung bei <code>TRUE</code>, Single-Shot-Ausführung bis Tabellenende bei <code>FALSE</code>).</li>\n<li><strong>Referenzen:</strong></li>\n<li><code>+reference</code> <code>OsScheduleTableCounterRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsCounter</code> (<code>0..*</code>): Bindet die Schedule Table an die Zeitbasis eines konkreten OS-Counters.</li>\n<li><strong>Sub-Container:</strong></li>\n<li><code>+subContainer</code> <code>OsScheduleTableExpiryPoint</code> (<code>1..*</code>): Mindestens ein Ablaufpunkt ist zwingend vorgeschrieben.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>OsScheduleTableExpiryPoint</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>):</li>\n<li>Repräsentiert einen diskreten Schaltzeitpunkt auf der Zeitachse der Schedule Table.</li>\n<li><strong>Parameter:</strong></li>\n<li><code>OsScheduleTblExpPointOffset</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Relativer Zeitversatz (in Ticks des zugeordneten Counters) ab Beginn der Tabelle.</li>\n<li><strong>Sub-Container:</strong></li>\n<li><code>+subContainer</code> <code>OsScheduleTblAdjustableExpPoint</code> (<code>0..1</code>): Optionaler Container für Synchronisationsanpassungen bei externer Zeitangleichung (Synchronous Schedule Tables).</li>\n<li><code>OsScheduleTableMaxShorten</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Maximal zulässige Verkürzung des Intervalls in Ticks zum Vorziehen des Expiry Points.</li>\n<li><code>OsScheduleTableMaxLengthen</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Maximal zulässige Dehnung des Intervalls in Ticks zum Verzögern des Expiry Points.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableTaskActivation</code> (<code>0..*</code>): Definiert Task-Aktivierungsaktionen an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableActivateTaskRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den zu aktivierenden Ziel-Task.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableEventSetting</code> (<code>0..*</code>): Definiert Event-Setzungen für Extended Tasks an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableSetEventRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsEvent</code> (<code>0..*</code>): Referenziert das zu setzende Event.</li>\n<li><code>+reference</code> <code>OsScheduleTableSetEventTaskRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den Ziel-Task, an den das Event übergeben wird.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Externe OS-Referenzziele (<code>from OS</code>):</strong></li>\n<li><code>OsCounter</code>: Bereitsteller der Ticks.</li>\n<li><code>OsTask</code>: Empfänger von Aktivierungen oder Events.</li>\n<li><code>OsEvent</code>: OS-Synchronisationsobjekt für Extended Tasks.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus dem statischen Konfigurationsmodell resultiert folgendes OS-Laufzeitverhalten:</p>\n<ol class=\"fig-list\">\n<li><strong>Start & Fortschritt:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Tabelle wird über OS-APIs gestartet (z. B. <code>StartScheduleTableRel()</code>, <code>StartScheduleTableAbs()</code> oder <code>StartScheduleTableSynchron()</code>).</li>\n<li>Der zugeordnete <code>OsCounter</code> inkrementiert fortlaufend. Das OS evaluiert die Differenz zum nächsten <code>OsScheduleTblExpPointOffset</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering am Expiry Point:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erreicht der Counter den Wert eines <code>OsScheduleTableExpiryPoint</code>:</li>\n<li>Für jeden <code>OsScheduleTableTaskActivation</code>-Container führt das OS intern ein äquivalentes <code>ActivateTask(TaskID)</code> aus.</li>\n<li>Für jeden <code>OsScheduleTableEventSetting</code>-Container führt das OS intern ein äquivalentes <code>SetEvent(TaskID, Mask)</code> aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationspfad (Dynamische Anpassung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft die Tabelle synchronisiert (z. B. mit einem globalen Bus-Zyklus über FlexRay oder StbM) und wird eine Phasendrift erkannt (<code>SyncScheduleTable()</code>), moduliert der OS-Scheduler die realen Abstände um maximal <code>OsScheduleTableMaxShorten</code> bzw. <code>OsScheduleTableMaxLengthen</code> an Punkten mit <code>OsScheduleTblAdjustableExpPoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklusabschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Erreichen der Gesamtdauer (<code>OsScheduleTableDuration</code>, Bestandteil von Teil 2):</li>\n<li>Ist <code>OsScheduleTableRepeating == TRUE</code>: Automatischer Wrap-around auf Offset 0.</li>\n<li>Ist <code>OsScheduleTableRepeating == FALSE</code>: Zustandsübergang nach <code>SCHEDULETABLE_STOPPED</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Validierungsregeln & Konsistenzprüfung:</strong></li>\n<li><code>OsScheduleTableEventSetting</code>: Der referenzierte <code>OsTask</code> (<code>OsScheduleTableSetEventTaskRef</code>) muss zwingend ein <strong>Extended Task</strong> sein und das referenzierte <code>OsEvent</code> (<code>OsScheduleTableSetEventRef</code>) in seiner Task-Konfiguration (<code>OsTaskEventRef</code>) besitzen. Code-Generatoren müssen hier statische Validierungsfehler werfen.</li>\n<li>Mindestens ein <code>OsScheduleTableExpiryPoint</code> ist Pflicht (<code>lowerMultiplicity = 1</code>). Ein leeres Ablaufgitter ist unzulässig.</li>\n<li>Offsets müssen streng monoton steigend oder innerhalb der Tabellendauer eindeutig geordnet sein, um deterministisches Scheduling sicherzustellen.</li>\n<li><strong>Synchronisation & Jitter:</strong></li>\n<li>Ist eine Schedule Table für Synchronisation vorgesehen (explizit/implizit), müssen die Summen von <code>OsScheduleTableMaxShorten</code> und <code>OsScheduleTableMaxLengthen</code> der einstellbaren Punkte die maximal erwartete Bus-/Globalzeit-Drift innerhalb einer Periode ausgleichen können, ohne dass benachbarte Expiry Points kollidieren oder Tasks ihre Deadline verletzen.</li>\n<li><strong>Laufzeit-Overhead:</strong></li>\n<li>Mehrere Task-Aktivierungen und Event-Setzungen am selben Expiry Point werden sequenziell innerhalb des OS-Timer-Tick-Kontexts (meist ISR Cat 2) verarbeitet. Dies erhöht direkt die Interrupt-Latenz und Blockierzeit niederpriorer Tasks.</li>\n</ul>"}, {"id": "FIG-311d461c2b78cb27", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Darstellung des AUTOSAR ECUC-Parameter-Definitions-Metamodells (ECU Configuration Parameter Definition) für das BSW-Modul <code>Os</code>.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Konfigurationscontainer, Parameter und Referenzen zur statischen Modellierung von AUTOSAR-OS-Ablaufplänen (<code>OsScheduleTable</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient BSW-Konfigurationstools und dem OS-Code-Generator zur deterministischen Generierung zeitgesteuerter Aktivierungs- und Synchronisationsmechanismen (AUTOSAR OS Skalierbarkeitsklassen SC2 und SC4) auf Basis von Hardware- oder Software-Zählern (<code>OsCounter</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Entitäten & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsScheduleTable</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>0..*</code>):</li>\n<li>Wurzelcontainer einer Schedule Table.</li>\n<li><strong>Parameter:</strong></li>\n<li><code>OsScheduleTableRepeating</code> (<code>EcucBooleanParamDef</code>, <code>1..1</code>): Definiert den Betriebsmodus (zyklische Wiederholung bei <code>TRUE</code>, Single-Shot-Ausführung bis Tabellenende bei <code>FALSE</code>).</li>\n<li><strong>Referenzen:</strong></li>\n<li><code>+reference</code> <code>OsScheduleTableCounterRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsCounter</code> (<code>0..*</code>): Bindet die Schedule Table an die Zeitbasis eines konkreten OS-Counters.</li>\n<li><strong>Sub-Container:</strong></li>\n<li><code>+subContainer</code> <code>OsScheduleTableExpiryPoint</code> (<code>1..*</code>): Mindestens ein Ablaufpunkt ist zwingend vorgeschrieben.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>OsScheduleTableExpiryPoint</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>):</li>\n<li>Repräsentiert einen diskreten Schaltzeitpunkt auf der Zeitachse der Schedule Table.</li>\n<li><strong>Parameter:</strong></li>\n<li><code>OsScheduleTblExpPointOffset</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Relativer Zeitversatz (in Ticks des zugeordneten Counters) ab Beginn der Tabelle.</li>\n<li><strong>Sub-Container:</strong></li>\n<li><code>+subContainer</code> <code>OsScheduleTblAdjustableExpPoint</code> (<code>0..1</code>): Optionaler Container für Synchronisationsanpassungen bei externer Zeitangleichung (Synchronous Schedule Tables).</li>\n<li><code>OsScheduleTableMaxShorten</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Maximal zulässige Verkürzung des Intervalls in Ticks zum Vorziehen des Expiry Points.</li>\n<li><code>OsScheduleTableMaxLengthen</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Maximal zulässige Dehnung des Intervalls in Ticks zum Verzögern des Expiry Points.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableTaskActivation</code> (<code>0..*</code>): Definiert Task-Aktivierungsaktionen an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableActivateTaskRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den zu aktivierenden Ziel-Task.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableEventSetting</code> (<code>0..*</code>): Definiert Event-Setzungen für Extended Tasks an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableSetEventRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsEvent</code> (<code>0..*</code>): Referenziert das zu setzende Event.</li>\n<li><code>+reference</code> <code>OsScheduleTableSetEventTaskRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den Ziel-Task, an den das Event übergeben wird.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Externe OS-Referenzziele (<code>from OS</code>):</strong></li>\n<li><code>OsCounter</code>: Bereitsteller der Ticks.</li>\n<li><code>OsTask</code>: Empfänger von Aktivierungen oder Events.</li>\n<li><code>OsEvent</code>: OS-Synchronisationsobjekt für Extended Tasks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus dem statischen Konfigurationsmodell resultiert folgendes OS-Laufzeitverhalten:</p>\n<ol class=\"fig-list\">\n<li><strong>Start & Fortschritt:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Tabelle wird über OS-APIs gestartet (z. B. <code>StartScheduleTableRel()</code>, <code>StartScheduleTableAbs()</code> oder <code>StartScheduleTableSynchron()</code>).</li>\n<li>Der zugeordnete <code>OsCounter</code> inkrementiert fortlaufend. Das OS evaluiert die Differenz zum nächsten <code>OsScheduleTblExpPointOffset</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering am Expiry Point:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erreicht der Counter den Wert eines <code>OsScheduleTableExpiryPoint</code>:</li>\n<li>Für jeden <code>OsScheduleTableTaskActivation</code>-Container führt das OS intern ein äquivalentes <code>ActivateTask(TaskID)</code> aus.</li>\n<li>Für jeden <code>OsScheduleTableEventSetting</code>-Container führt das OS intern ein äquivalentes <code>SetEvent(TaskID, Mask)</code> aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationspfad (Dynamische Anpassung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft die Tabelle synchronisiert (z. B. mit einem globalen Bus-Zyklus über FlexRay oder StbM) und wird eine Phasendrift erkannt (<code>SyncScheduleTable()</code>), moduliert der OS-Scheduler die realen Abstände um maximal <code>OsScheduleTableMaxShorten</code> bzw. <code>OsScheduleTableMaxLengthen</code> an Punkten mit <code>OsScheduleTblAdjustableExpPoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklusabschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Erreichen der Gesamtdauer (<code>OsScheduleTableDuration</code>, Bestandteil von Teil 2):</li>\n<li>Ist <code>OsScheduleTableRepeating == TRUE</code>: Automatischer Wrap-around auf Offset 0.</li>\n<li>Ist <code>OsScheduleTableRepeating == FALSE</code>: Zustandsübergang nach <code>SCHEDULETABLE_STOPPED</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Validierungsregeln & Konsistenzprüfung:</strong></li>\n<li><code>OsScheduleTableEventSetting</code>: Der referenzierte <code>OsTask</code> (<code>OsScheduleTableSetEventTaskRef</code>) muss zwingend ein <strong>Extended Task</strong> sein und das referenzierte <code>OsEvent</code> (<code>OsScheduleTableSetEventRef</code>) in seiner Task-Konfiguration (<code>OsTaskEventRef</code>) besitzen. Code-Generatoren müssen hier statische Validierungsfehler werfen.</li>\n<li>Mindestens ein <code>OsScheduleTableExpiryPoint</code> ist Pflicht (<code>lowerMultiplicity = 1</code>). Ein leeres Ablaufgitter ist unzulässig.</li>\n<li>Offsets müssen streng monoton steigend oder innerhalb der Tabellendauer eindeutig geordnet sein, um deterministisches Scheduling sicherzustellen.</li>\n<li><strong>Synchronisation & Jitter:</strong></li>\n<li>Ist eine Schedule Table für Synchronisation vorgesehen (explizit/implizit), müssen die Summen von <code>OsScheduleTableMaxShorten</code> und <code>OsScheduleTableMaxLengthen</code> der einstellbaren Punkte die maximal erwartete Bus-/Globalzeit-Drift innerhalb einer Periode ausgleichen können, ohne dass benachbarte Expiry Points kollidieren oder Tasks ihre Deadline verletzen.</li>\n<li><strong>Laufzeit-Overhead:</strong></li>\n<li>Mehrere Task-Aktivierungen und Event-Setzungen am selben Expiry Point werden sequenziell innerhalb des OS-Timer-Tick-Kontexts (meist ISR Cat 2) verarbeitet. Dies erhöht direkt die Interrupt-Latenz und Blockierzeit niederpriorer Tasks.</li>\n</ul>"}, {"id": "FIG-3ac48528509d613f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm zur Darstellung des AUTOSAR ECUC-Parameter-Definitions-Metamodells (ECU Configuration Parameter Definition) für das BSW-Modul <code>Os</code>.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Konfigurationscontainer, Parameter und Referenzen zur statischen Modellierung von AUTOSAR-OS-Ablaufplänen (<code>OsScheduleTable</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient BSW-Konfigurationstools und dem OS-Code-Generator zur deterministischen Generierung zeitgesteuerter Aktivierungs- und Synchronisationsmechanismen (AUTOSAR OS Skalierbarkeitsklassen SC2 und SC4) auf Basis von Hardware- oder Software-Zählern (<code>OsCounter</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Entitäten & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsScheduleTable</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>0..*</code>):</li>\n<li>Wurzelcontainer einer Schedule Table.</li>\n<li><strong>Parameter:</strong></li>\n<li><code>OsScheduleTableRepeating</code> (<code>EcucBooleanParamDef</code>, <code>1..1</code>): Definiert den Betriebsmodus (zyklische Wiederholung bei <code>TRUE</code>, Single-Shot-Ausführung bis Tabellenende bei <code>FALSE</code>).</li>\n<li><strong>Referenzen:</strong></li>\n<li><code>+reference</code> <code>OsScheduleTableCounterRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsCounter</code> (<code>0..*</code>): Bindet die Schedule Table an die Zeitbasis eines konkreten OS-Counters.</li>\n<li><strong>Sub-Container:</strong></li>\n<li><code>+subContainer</code> <code>OsScheduleTableExpiryPoint</code> (<code>1..*</code>): Mindestens ein Ablaufpunkt ist zwingend vorgeschrieben.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>OsScheduleTableExpiryPoint</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>):</li>\n<li>Repräsentiert einen diskreten Schaltzeitpunkt auf der Zeitachse der Schedule Table.</li>\n<li><strong>Parameter:</strong></li>\n<li><code>OsScheduleTblExpPointOffset</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Relativer Zeitversatz (in Ticks des zugeordneten Counters) ab Beginn der Tabelle.</li>\n<li><strong>Sub-Container:</strong></li>\n<li><code>+subContainer</code> <code>OsScheduleTblAdjustableExpPoint</code> (<code>0..1</code>): Optionaler Container für Synchronisationsanpassungen bei externer Zeitangleichung (Synchronous Schedule Tables).</li>\n<li><code>OsScheduleTableMaxShorten</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Maximal zulässige Verkürzung des Intervalls in Ticks zum Vorziehen des Expiry Points.</li>\n<li><code>OsScheduleTableMaxLengthen</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Maximal zulässige Dehnung des Intervalls in Ticks zum Verzögern des Expiry Points.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableTaskReplenish</code> (<code>0..*</code>): Konfiguriert Aktionen zur Budget-Wiederauffüllung (Execution Budget Replenishment) für Tasks an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableReplenishTaskRef</code> (<code>EcucReferenceDef</code>, <code>1..1</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den Task, dessen Ausführungszeit-Budget aufgefüllt werden soll.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableTaskActivation</code> (<code>0..*</code>): Definiert Task-Aktivierungsaktionen an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableActivateTaskRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den zu aktivierenden Ziel-Task.</li>\n<li><code>+subContainer</code> <code>OsScheduleTableEventSetting</code> (<code>0..*</code>): Definiert Event-Setzungen für Extended Tasks an diesem Expiry Point.</li>\n<li><code>+reference</code> <code>OsScheduleTableSetEventRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsEvent</code> (<code>0..*</code>): Referenziert das zu setzende Event.</li>\n<li><code>+reference</code> <code>OsScheduleTableSetEventTaskRef</code> (<code>EcucReferenceDef</code>) $\\rightarrow$ <code>+destination</code> <code>OsTask</code> (<code>0..*</code>): Referenziert den Ziel-Task, an den das Event übergeben wird.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Externe OS-Referenzziele (<code>from OS</code>):</strong></li>\n<li><code>OsCounter</code>: Bereitsteller der Ticks.</li>\n<li><code>OsTask</code>: Empfänger von Aktivierungen, Events oder Budget-Auffüllungen.</li>\n<li><code>OsEvent</code>: OS-Synchronisationsobjekt für Extended Tasks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus dem statischen Konfigurationsmodell resultiert folgendes OS-Laufzeitverhalten:</p>\n<ol class=\"fig-list\">\n<li><strong>Start & Fortschritt:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Tabelle wird über OS-APIs gestartet (z. B. <code>StartScheduleTableRel()</code>, <code>StartScheduleTableAbs()</code> oder <code>StartScheduleTableSynchron()</code>).</li>\n<li>Der zugeordnete <code>OsCounter</code> inkrementiert fortlaufend. Das OS evaluiert die Differenz zum nächsten <code>OsScheduleTblExpPointOffset</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering am Expiry Point:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erreicht der Counter den Wert eines <code>OsScheduleTableExpiryPoint</code>:</li>\n<li>Für jeden <code>OsScheduleTableTaskActivation</code>-Container führt das OS intern ein äquivalentes <code>ActivateTask(TaskID)</code> aus.</li>\n<li>Für jeden <code>OsScheduleTableEventSetting</code>-Container führt das OS intern ein äquivalentes <code>SetEvent(TaskID, Mask)</code> aus.</li>\n<li>Für jeden <code>OsScheduleTableTaskReplenish</code>-Container triggert das OS eine Budget-Wiederauffüllung (Execution Budget Replenishment) des referenzierten <code>OsTask</code> im Rahmen der Timing-Protection-Überwachung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationspfad (Dynamische Anpassung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft die Tabelle synchronisiert (z. B. mit einem globalen Bus-Zyklus über FlexRay oder StbM) und wird eine Phasendrift erkannt (<code>SyncScheduleTable()</code>), moduliert der OS-Scheduler die realen Abstände um maximal <code>OsScheduleTableMaxShorten</code> bzw. <code>OsScheduleTableMaxLengthen</code> an Punkten mit <code>OsScheduleTblAdjustableExpPoint</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklusabschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Erreichen der Gesamtdauer (<code>OsScheduleTableDuration</code>, Bestandteil von Teil 2):</li>\n<li>Ist <code>OsScheduleTableRepeating == TRUE</code>: Automatischer Wrap-around auf Offset 0.</li>\n<li>Ist <code>OsScheduleTableRepeating == FALSE</code>: Zustandsübergang nach <code>SCHEDULETABLE_STOPPED</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Validierungsregeln & Konsistenzprüfung:</strong></li>\n<li><code>OsScheduleTableEventSetting</code>: Der referenzierte <code>OsTask</code> (<code>OsScheduleTableSetEventTaskRef</code>) muss zwingend ein <strong>Extended Task</strong> sein und das referenzierte <code>OsEvent</code> (<code>OsScheduleTableSetEventRef</code>) in seiner Task-Konfiguration (<code>OsTaskEventRef</code>) besitzen. Code-Generatoren müssen hier statische Validierungsfehler werfen.</li>\n<li><code>OsScheduleTableTaskReplenish</code>: Der referenzierte <code>OsTask</code> (<code>OsScheduleTableReplenishTaskRef</code>) muss für Timing Protection bzw. Execution Budget Monitoring konfiguriert sein. Die Referenz ist obligatorisch (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li>Mindestens ein <code>OsScheduleTableExpiryPoint</code> ist Pflicht (<code>lowerMultiplicity = 1</code>). Ein leeres Ablaufgitter ist unzulässig.</li>\n<li>Offsets müssen streng monoton steigend oder innerhalb der Tabellendauer eindeutig geordnet sein, um deterministisches Scheduling sicherzustellen.</li>\n<li><strong>Synchronisation & Jitter:</strong></li>\n<li>Ist eine Schedule Table für Synchronisation vorgesehen (explizit/implizit), müssen die Summen von <code>OsScheduleTableMaxShorten</code> und <code>OsScheduleTableMaxLengthen</code> der einstellbaren Punkte die maximal erwartete Bus-/Globalzeit-Drift innerhalb einer Periode ausgleichen können, ohne dass benachbarte Expiry Points kollidieren oder Tasks ihre Deadline verletzen.</li>\n<li><strong>Laufzeit-Overhead:</strong></li>\n<li>Mehrere Task-Aktivierungen, Event-Setzungen und Budget-Replenishments am selben Expiry Point werden sequenziell innerhalb des OS-Timer-Tick-Kontexts (meist ISR Cat 2) verarbeitet. Dies erhöht direkt die Interrupt-Latenz und Blockierzeit niederpriorer Tasks.</li>\n</ul>"}], "trans": [{"from": "FIG-976fec5bf990e4d8", "to": "FIG-311d461c2b78cb27", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-311d461c2b78cb27", "to": "FIG-3ac48528509d613f", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Container <code>OsScheduleTableExpiryPoint</code>: Neuer Sub-Container <code>OsScheduleTableTaskReplenish</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>0..*</code>) hinzugefügt.</li>\n<li>Container <code>OsScheduleTableTaskReplenish</code>: Neue Referenz <code>OsScheduleTableReplenishTaskRef</code> (<code>EcucReferenceDef</code>, Multiplizität: <code>1..1</code>) mit Ziel <code>OsTask</code> ergänzt.</li>\n</ul>"}]};
